        "P(k) = N / (1 + k^2) for Poisson",
        "P(k) = N / (1 + k^2)^2 for GUE",
        "P(k -> infinity) proportional to |k|^(-beta_tilde) with beta_tilde = 2 (Poisson) or 4 (GUE)"
      ],
      "variable_names": [
        "k",
        "kappa_n",
        "Delta",
        "Var(dt phi_n)",
        "beta_tilde",
        "N_POI",
        "N_GUE"
      ],
